MODULES_H = """\
// Generated by xewe modules generate; do not edit. Re-run ./setup.sh or `xewe modules select` to change modules.
// Included by the sketch after `os`; modules are declared in dependency order.
#pragma once

#include <XeWeModules.h>

Wifi wifi(os);
Time time_module(os, wifi);
Scheduler scheduler(os, time_module);
WebInterface web_interface(os, wifi);
"""

XEWE_MODULES_H = """\
// Generated by xewe modules generate; do not edit. The selected XeWe OS modules in dependency order.
#pragma once

#include "Wifi/Wifi.h"
#include "Time/Time.h"
#include "Scheduler/Scheduler.h"
#include "WebInterface/WebInterface.h"
"""

LIBRARY_PROPERTIES = """\
name=XeWeModules
version=1.0.0
author=xewe-labs
maintainer=xewe-labs
sentence=The XeWe OS modules selected for this project; generated by xewe modules generate, do not edit.
paragraph=Modules: wifi, web-interface.
category=Other
url=https://github.com/xewe-labs/xewe-os-modules
architectures=esp32
depends=XeWeCore
includes=XeWeModules.h
"""
LOCK_HEADER = "# generated by xewe: slug|folder|source|ref|commit\n"


@pytest.fixture(params=["modules", "legacy"])
def checkout(request: pytest.FixtureRequest, tmp_path: Path) -> Path:
    return make_modules_checkout(tmp_path / "checkout", request.param)


def bars(name: str) -> str:
    """The bar, the ``start`` line and the bar of a block."""
    line = f"/* ---- start {name} ---- */"
    bar = "/" + "*" * (len(line) - 2) + "/"
    return f"{bar}\n{line}\n{bar}\n"


def end_bars(name: str) -> str:
    """The bar, the ``end`` line and the bar of a block."""
    line = f"/* ---- end {name} ---- */"
    bar = "/" + "*" * (len(line) - 2) + "/"
    return f"{bar}\n{line}\n{bar}\n"


def sections(runtime: str = "", constants: str = "") -> str:
    """The two sections of a block around ``runtime`` and ``constants`` (entry lines, or empty)."""
    out = []
    for name, body in (("default runtime values", runtime), ("compile time defined constants", constants)):
        inner = f"{body}\n" if body else ""
        out.append(f"/* ---- start {name} ---- */\n\n{inner}{'' if not body else chr(10)}/* ---- end {name} ---- */\n")
    return "\n".join(out)


PINS_CONFIG_H = """\
// SPDX-FileCopyrightText: 2026 Someone
// SPDX-License-Identifier: GPL-3.0-only
// xewe-os-modules/modules/pins/src/Pins/Config.h
#pragma once

// Claim slots.
#ifndef XEWE_PINS_CLAIMS_MAX
#define XEWE_PINS_CLAIMS_MAX 8
#endif
"""
PINS_BLOCK = (
    bars("pins")
    + "// Claim slots.\n#ifndef XEWE_PINS_CLAIMS_MAX\n#define XEWE_PINS_CLAIMS_MAX 8\n#endif\n\n"
    + end_bars("pins")
)
PROJECT_CONFIG_H = "#pragma once\n#include <XeWeBuildInfo.h>\n"


def _module_config(checkout: Path, slug: str, text: str = PINS_CONFIG_H) -> None:
    """Give module ``slug`` of ``checkout`` a ``src/<Folder>/Config.h``."""
    folder = next(next(checkout.rglob(f"*{slug}/src")).iterdir())
    (folder / "Config.h").write_text(text)


def _set(checkout: Path, slug: str, key: str, value: str | None) -> None:
    props = next(checkout.rglob(f"*{slug}/module.properties"))
    lines = [ln for ln in props.read_text().splitlines() if not ln.startswith(f"{key}=")]
    if value is not None:
        lines.insert(0, f"{key}={value}")
    props.write_text("\n".join(lines) + "\n")


def test_registry_reads_both_layouts(checkout: Path) -> None:
    reg = Registry.load(checkout)
    assert reg.slugs() == ["buttons", "pins", "scheduler", "time", "web-interface", "wifi"]


def test_properties_first_key_wins() -> None:
    props, keys = modules.parse_properties("a=1\na=2\nb=x=y\n# c=3\n")
    assert props == {"a": "1", "b": "x=y"} and keys == ["a", "a", "b"]


def test_resolve_order_and_additions(checkout: Path, caplog: pytest.LogCaptureFixture) -> None:
    with caplog.at_level(logging.INFO, logger="xewe"):
        order = Registry.load(checkout).resolve(["scheduler", "web-interface"])
    assert [m.slug for m in order] == ["wifi", "time", "scheduler", "web-interface"]
    assert "scheduler requires time; adding it" in caplog.text
    assert "time requires wifi; adding it" in caplog.text
    assert modules.render_modules_h(order) == MODULES_H
    assert modules.render_library_h(order) == XEWE_MODULES_H


def test_cycle_is_an_error(checkout: Path) -> None:
    _set(checkout, "wifi", "depends_modules", "scheduler")
    with pytest.raises(XeWeError, match="dependency cycle through module"):
        Registry.load(checkout).resolve(["scheduler"])


def test_unknown_module_is_usage_error(checkout: Path) -> None:
    with pytest.raises(XeWeError) as exc:
        Registry.load(checkout).resolve(["nope"])
    assert exc.value.code == 2


def test_generate_writes_modules(tmp_path: Path, checkout: Path) -> None:
    p = Paths(tmp_path / "proj")
    order = modules.generate(
        p, Registry.load(checkout), ["wifi", "web-interface"], "https://x/mods", "v1.0.0", "c0ffee"
    )
    assert [m.slug for m in order] == ["wifi", "web-interface"]
    assert sorted(f.name for f in p.modules.iterdir()) == ["library.properties", "modules.lock", "src"]
    assert sorted(f.name for f in (p.modules / "src").iterdir()) == ["WebInterface", "Wifi", "XeWeModules.h"]
    assert (p.modules / "src" / "Wifi" / "Wifi.h").is_file()
    assert (p.modules / "library.properties").read_text() == LIBRARY_PROPERTIES
    assert (
        (p.modules / "src" / "XeWeModules.h")
        .read_text()
        .endswith('#include "Wifi/Wifi.h"\n#include "WebInterface/WebInterface.h"\n')
    )
    text = p.src_modules_h.read_text()
    assert text.startswith("// Generated by xewe modules generate; do not edit.")
    assert text.endswith("#include <XeWeModules.h>\n\nWifi wifi(os);\nWebInterface web_interface(os, wifi);\n")
    assert p.modules_lock.read_text() == (
        LOCK_HEADER + "wifi|Wifi|https://x/mods|v1.0.0|c0ffee\n"
        "web-interface|WebInterface|https://x/mods|v1.0.0|c0ffee\n"
    )
    assert p.modules_lock == p.root / "build" / "modules" / "modules.lock"
    assert sorted(f.name for f in p.root.iterdir()) == ["build", "src"]
    assert sorted(f.name for f in (p.root / "src").iterdir()) == ["Modules.h"]  # no src/modules/ any more
    assert sorted(f.name for f in p.build.iterdir()) == ["modules"]  # staging swapped away, build/tmp removed


def test_generate_appends_config_blocks(tmp_path: Path, checkout: Path, capsys: pytest.CaptureFixture[str]) -> None:
    _module_config(checkout, "pins")
    _module_config(checkout, "wifi", "#pragma once\n#ifndef XEWE_WIFI_DEBUG\n#define XEWE_WIFI_DEBUG 0\n#endif\n")
    p = Paths(tmp_path / "proj")
    p.root.mkdir()
    config_h = p.root / "Config.h"
    config_h.write_text(PROJECT_CONFIG_H)
    assert Registry.load(checkout).get("pins").config_h is not None
    assert Registry.load(checkout).get("buttons").config_h is None
    modules.generate(p, Registry.load(checkout), ["pins", "buttons", "wifi"], "s", "r", "c")
    text = config_h.read_text()
    assert text == PROJECT_CONFIG_H + "\n" + PINS_BLOCK + "\n" + (
        bars("wifi") + "#ifndef XEWE_WIFI_DEBUG\n#define XEWE_WIFI_DEBUG 0\n#endif\n\n" + end_bars("wifi")
    )
    assert "buttons" not in text  # a module without Config.h adds no block
    # a second generate is a no-op, byte for byte
    modules.generate(p, Registry.load(checkout), ["pins", "buttons", "wifi"], "s", "r", "c")
    assert config_h.read_text() == text
    # an edited value survives; the block is never rewritten
    edited = text.replace("CLAIMS_MAX 8", "CLAIMS_MAX 16")
    config_h.write_text(edited)
    capsys.readouterr()
    modules.generate(p, Registry.load(checkout), ["pins", "wifi"], "s", "r", "c")
    assert config_h.read_text() == edited
    assert "note:" not in capsys.readouterr().out
    # deselecting keeps the block and says so
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert config_h.read_text() == edited
    assert "note: Config.h keeps the pins block; the module is not selected" in capsys.readouterr().out


