def test_generate_empty_selection(tmp_path: Path, checkout: Path) -> None:
    p = Paths(tmp_path / "proj")
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert modules.generate(p, Registry.load(checkout), [], "https://x/mods", "v1.0.0", "c0ffee") == []
    assert sorted(f.name for f in p.modules.iterdir()) == ["library.properties", "modules.lock", "src"]
    assert sorted(f.name for f in (p.modules / "src").iterdir()) == ["XeWeModules.h"]
    props = (p.modules / "library.properties").read_text()
    assert "name=XeWeModules\n" in props and "paragraph=Modules: none.\n" in props
    lib_h = (p.modules / "src" / "XeWeModules.h").read_text()
    assert "#pragma once\n" in lib_h and "#include" not in lib_h
    text = p.src_modules_h.read_text()
    assert text.startswith("// Generated by xewe modules generate") and "#pragma once\n" in text
    assert "#include <XeWeModules.h>\n" in text and text.count("#include") == 1 and "(os" not in text
    assert p.modules_lock.read_text() == LOCK_HEADER


def test_generate_copies_module_tests(tmp_path: Path) -> None:
    checkout = make_modules_checkout(tmp_path / "c", "modules", board_tests=True)
    wifi = checkout / "modules" / "wifi" / "tests"
    (wifi / "unit").mkdir()
    (wifi / "unit" / "test_logic.py").write_text("")
    (wifi / "board" / "__pycache__").mkdir()
    p = Paths(tmp_path / "proj")
    modules.generate(p, Registry.load(checkout), ["web-interface"], "s", "r", "c")  # wifi comes as a dependency
    assert sorted(f.name for f in p.modules.iterdir()) == ["library.properties", "modules.lock", "src", "tests"]
    assert sorted(f.name for f in (p.modules / "tests").iterdir()) == ["web-interface", "wifi"]
    assert sorted(f.name for f in p.module_tests("wifi").iterdir()) == ["board", "unit"]
    assert sorted(f.name for f in (p.module_tests("wifi") / "board").iterdir()) == ["test_wifi.py"]
    assert (p.module_tests("web-interface") / "board" / "test_web-interface.py").is_file()
    # a new selection replaces the tests too
    modules.generate(p, Registry.load(checkout), ["pins"], "s", "r", "c")
    assert sorted(f.name for f in (p.modules / "tests").iterdir()) == ["pins"]


def test_module_dir_in_repo_and_from_project_copy(project: Paths, tmp_path: Path) -> None:
    from xewe.testing import module_dir

    wifi = tmp_path / "modules-src" / "modules" / "wifi"  # the recorded checkout (XEWE_MODULES_SOURCE)
    assert module_dir(wifi / "tests" / "unit" / "test_wifi.py") == wifi
    copy = project.module_tests("wifi") / "unit" / "test_wifi.py"
    copy.parent.mkdir(parents=True, exist_ok=True)
    copy.write_text("")
    assert module_dir(copy) == wifi


def test_generate_removes_previous_layout(tmp_path: Path, checkout: Path, capsys: pytest.CaptureFixture[str]) -> None:
    p = Paths(tmp_path / "proj")
    (p.build / "modules-lib" / "src").mkdir(parents=True)
    (p.build / "modules" / "modules").mkdir(parents=True)  # the old in-project modules checkout
    p.config_dir.mkdir()
    (p.config_dir / "modules.lock").write_text(LOCK_HEADER)
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert sorted(f.name for f in p.build.iterdir()) == ["config", "modules"]
    assert list(p.config_dir.iterdir()) == []
    assert sorted(f.name for f in p.modules.iterdir()) == ["library.properties", "modules.lock", "src"]
    out = capsys.readouterr().out
    assert "removed legacy build/modules-lib" in out and "removed legacy build/config/modules.lock" in out


def test_generate_removes_legacy_src_modules(
    tmp_path: Path, checkout: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    p = Paths(tmp_path / "proj")
    legacy = p.root / "src" / "modules"
    (legacy / "Wifi").mkdir(parents=True)
    (legacy / "Modules.h").write_text("// old\n")
    (legacy / "modules.lock").write_text(LOCK_HEADER + "wifi|Wifi|s|r|c\n")
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert not legacy.exists()
    assert "removed legacy src/modules/" in capsys.readouterr().out


@pytest.mark.parametrize("lock_text", [None, "# my own notes\n", ""])
def test_generate_keeps_src_modules_it_did_not_write(
    tmp_path: Path, checkout: Path, lock_text: str | None, capsys: pytest.CaptureFixture[str]
) -> None:
    p = Paths(tmp_path / "proj")
    own = p.root / "src" / "modules"
    own.mkdir(parents=True)
    (own / "Mine.h").write_text("// the owner's code\n")
    if lock_text is not None:
        (own / "modules.lock").write_text(lock_text)
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert (own / "Mine.h").is_file()
    assert "removed legacy" not in capsys.readouterr().out


