@pytest.mark.parametrize(
    ("entry", "message"),
    [
        ("tests/test_wifi.py", "tests/test_wifi.py not allowed"),
        ("tests/host/test_x.cpp", "tests/host not allowed"),
        ("tests/conftest.py", "tests/conftest.py not allowed"),
        ("tests/board/conftest.py", "tests/board/conftest.py not allowed"),
        ("tests/unit/__init__.py", "tests/unit/__init__.py not allowed"),
        ("tests/unit", "tests/board/test_wifi.py missing"),
    ],
)
def test_tests_layout_rules(tmp_path: Path, entry: str, message: str) -> None:
    checkout = make_modules_checkout(tmp_path / "c", "modules", board_tests=True)
    wifi = checkout / "modules" / "wifi"
    if message.endswith("missing"):
        (wifi / "tests" / "board" / "test_wifi.py").unlink()
    path = wifi / entry
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.suffix:
        path.write_text("")
    else:
        path.mkdir(exist_ok=True)
    errors = [str(p) for p in modules.check_tests_layout(Registry.load(checkout)) if p.error]
    assert any(message in e and e.startswith("error: wifi:") for e in errors), errors


